package com.pixarch.app.core.clip

import android.content.Context
import java.io.BufferedInputStream
import java.io.BufferedReader
import java.io.FileNotFoundException
import java.io.InputStream
import java.io.InputStreamReader
import java.text.Normalizer
import java.util.regex.Pattern
import java.util.zip.GZIPInputStream

/**
 * Kotlin port of OpenCLIP's `SimpleTokenizer` (the tokenizer MobileCLIP2-S0 uses).
 *
 * Must stay token-for-token identical to `open_clip.get_tokenizer("MobileCLIP2-S0")`:
 * `ClipTokenizerTest` checks it against fixtures generated by
 * `scripts/make_edge_fixtures.py`. Known gap: Python also runs `ftfy.fix_text` and
 * `html.unescape`; only the NFC normalisation part of ftfy is reproduced here.
 */
class ClipTokenizer(openVocab: () -> InputStream) {

    /**
     * The Android build (aapt) gunzips `*.gz` assets and strips the suffix, so the APK
     * holds `tokenizer/bpe_simple_vocab_16e6.txt`. Try the name as given, then without
     * `.gz`; gzip is detected from the bytes, not the name.
     */
    constructor(
        context: Context,
        vocabAssetPath: String = "tokenizer/bpe_simple_vocab_16e6.txt.gz"
    ) : this({
        try {
            context.assets.open(vocabAssetPath)
        } catch (e: FileNotFoundException) {
            context.assets.open(vocabAssetPath.removeSuffix(".gz"))
        }
    })

    companion object {
        const val CONTEXT_LENGTH = 77

        /**
         * The vocab file holds ~262k merges but CLIP's 49,408-token vocabulary uses only
         * the first 48,894 (49152 - 256 - 2). Loading more creates token ids beyond the
         * model's embedding table, which crashes the text encoder or silently corrupts
         * the EOT ArgMax.
         */
        const val NUM_MERGES = 49152 - 256 - 2

        const val SOT = "<start_of_text>"
        const val EOT = "<end_of_text>"

        // Must compile on Android's ICU regex engine, which rejects UNICODE_CHARACTER_CLASS
        // (and `(?U)`). \p{L}/\p{N} are Unicode-aware everywhere. Python's `\s` is
        // Unicode-wide, so clean() first collapses all Unicode whitespace to ' ' and the
        // pattern only ever needs to exclude a plain space.
        private val PATTERN = Pattern.compile(
            "<start_of_text>|<end_of_text>|'s|'t|'re|'ve|'m|'ll|'d|[\\p{L}]+|[\\p{N}]|[^ \\p{L}\\p{N}]+",
            Pattern.CASE_INSENSITIVE
        )

        private fun bytesToUnicode(): Map<Int, Char> {
            val bs = mutableListOf<Int>()
            for (b in '!'.code..'~'.code) bs.add(b)
            for (b in '¡'.code..'¬'.code) bs.add(b)
            for (b in '®'.code..'ÿ'.code) bs.add(b)

            val cs = bs.toMutableList()
            var n = 0
            for (b in 0..255) {
                if (b !in bs) {
                    bs.add(b)
                    cs.add(256 + n)
                    n++
                }
            }
            return bs.indices.associate { bs[it] to cs[it].toChar() }
        }
    }

    private val byteEncoder = bytesToUnicode()
    private val bpeRanks = HashMap<Pair<String, String>, Int>(NUM_MERGES * 2)
    private val encoder = HashMap<String, Long>(60_000)
    private val cache = HashMap<String, List<String>>()

    val sotToken: Long
    val eotToken: Long

    init {
        val merges = ArrayList<Pair<String, String>>(NUM_MERGES)
        openVocab().use { raw ->
            val buffered = BufferedInputStream(raw)
            buffered.mark(2)
            val isGzip = buffered.read() == 0x1f && buffered.read() == 0x8b
            buffered.reset()
            val stream = if (isGzip) GZIPInputStream(buffered) else buffered
            BufferedReader(InputStreamReader(stream, Charsets.UTF_8)).use { reader ->
                reader.readLine() // header line ("#version: 0.2")
                while (merges.size < NUM_MERGES) {
                    val line = reader.readLine() ?: break
                    val parts = line.split(" ")
                    if (parts.size == 2) merges.add(parts[0] to parts[1])
                }
            }
        }
        check(merges.size == NUM_MERGES) {
            "BPE vocab truncated: expected $NUM_MERGES merges, read ${merges.size}"
        }
        merges.forEachIndexed { rank, pair -> bpeRanks[pair] = rank }

        // Same order as Python: bytes, bytes+</w>, merges, specials. Python builds the
        // map with dict(zip(vocab, range(...))), so a repeated entry keeps its last index.
        val vocab = ArrayList<String>(49_408)
        vocab.addAll(byteEncoder.values.map { it.toString() })
        vocab.addAll(byteEncoder.values.map { "$it</w>" })
        merges.forEach { vocab.add(it.first + it.second) }
        vocab.add(SOT)
        vocab.add(EOT)
        vocab.forEachIndexed { i, tok -> encoder[tok] = i.toLong() }

        sotToken = encoder.getValue(SOT)
        eotToken = encoder.getValue(EOT)
        cache[SOT] = listOf(SOT)
        cache[EOT] = listOf(EOT)
    }

    private fun getPairs(word: List<String>): Set<Pair<String, String>> {
        val pairs = HashSet<Pair<String, String>>()
        for (i in 0 until word.size - 1) pairs.add(word[i] to word[i + 1])
        return pairs
    }

    private fun bpe(token: String): List<String> {
        cache[token]?.let { return it }

        var word: List<String> = token.dropLast(1).map { it.toString() } + (token.last() + "</w>")
        var pairs = getPairs(word)
        if (pairs.isEmpty()) return listOf("$token</w>")

        while (true) {
            val bigram = pairs.minByOrNull { bpeRanks[it] ?: Int.MAX_VALUE } ?: break
            if (bigram !in bpeRanks) break
            val (first, second) = bigram

            val newWord = ArrayList<String>(word.size)
            var i = 0
            while (i < word.size) {
                var j = -1
                for (k in i until word.size) if (word[k] == first) { j = k; break }
                if (j == -1) {
                    newWord.addAll(word.subList(i, word.size))
                    break
                }
                newWord.addAll(word.subList(i, j))
                i = j
                if (i < word.size - 1 && word[i] == first && word[i + 1] == second) {
                    newWord.add(first + second)
                    i += 2
                } else {
                    newWord.add(word[i])
                    i += 1
                }
            }
            word = newWord
            if (word.size == 1) break
            pairs = getPairs(word)
        }
        cache[token] = word
        return word
    }

    private fun clean(text: String): String {
        val nfc = Normalizer.normalize(text, Normalizer.Form.NFC)
        // Equivalent of Python's re.sub(r"\s+", " ", text).strip(); Char.isWhitespace
        // covers Unicode spaces (NBSP, ideographic space, ...) like Python's str.isspace.
        val sb = StringBuilder(nfc.length)
        var pendingSpace = false
        for (c in nfc) {
            if (c.isWhitespace()) {
                pendingSpace = sb.isNotEmpty()
            } else {
                if (pendingSpace) sb.append(' ')
                pendingSpace = false
                sb.append(c)
            }
        }
        return sb.toString().lowercase()
    }

    /** BPE token ids for [text], without SOT/EOT or padding. */
    fun encodeIds(text: String): List<Long> {
        val ids = ArrayList<Long>()
        val matcher = PATTERN.matcher(clean(text))
        while (matcher.find()) {
            val piece = matcher.group()
            val mapped = buildString {
                for (b in piece.toByteArray(Charsets.UTF_8)) append(byteEncoder.getValue(b.toInt() and 0xFF))
            }
            for (bpeToken in bpe(mapped)) ids.add(encoder.getValue(bpeToken))
        }
        return ids
    }

    /** SOT + ids + EOT, truncated to 77 with EOT forced last, zero-padded. */
    @Synchronized
    fun encode(text: String): LongArray {
        val tokens = ArrayList<Long>(CONTEXT_LENGTH)
        tokens.add(sotToken)
        tokens.addAll(encodeIds(text))
        tokens.add(eotToken)

        val result = LongArray(CONTEXT_LENGTH)
        val n = minOf(tokens.size, CONTEXT_LENGTH)
        for (i in 0 until n) result[i] = tokens[i]
        if (tokens.size > CONTEXT_LENGTH) result[CONTEXT_LENGTH - 1] = eotToken
        return result
    }
}
